_choice_sftp_cipher() {
    command -v ssh >/dev/null 2>&1 || return 0
    ssh -Q cipher 2>/dev/null
}

_choice_sftp_command() {
    if [[ -n "$argc__option" ]]; then
        local -n ref="$argc__option"
        argc__positionals=( "${ref[@]}" )
        unset -n ref
    fi
