_choice_sftp_destination() {
    # An sftp:// URI is left as free text; splitting on ':' would treat the scheme as a host.
    if [[ "$ARGC_CWORD" == *://* ]]; then
        return 0
    fi
    _argc_util_mode_kv :
    if [[ -z "$argc__kv_prefix" ]]; then
        _choice_sftp_host | _argc_util_transform suffix=: nospace
    else
        local target="$argc__kv_key"
        local filter="$argc__kv_filter"
