BindAddress=;;local address to bind
CanonicalizeHostname=yes,no,always;;canonicalize host names
CheckHostIP=yes,no;;check the host IP address
Ciphers=`_choice_sftp_cipher`;;ciphers to use
ConnectTimeout=;;connection timeout in seconds
ConnectionAttempts=;;number of connection attempts
ForwardAgent=yes,no;;forward the authentication agent
GlobalKnownHostsFile=__argc_value=file;;global known hosts file
HostKeyAlgorithms=;;host key algorithms
Hostname=;;real host name
IdentityFile=__argc_value=file;;identity file
IdentitiesOnly=yes,no;;use only configured identities
KbdInteractiveAuthentication=yes,no;;keyboard-interactive authentication
KexAlgorithms=;;key exchange algorithms
LogLevel=QUIET,FATAL,ERROR,INFO,VERBOSE,DEBUG,DEBUG1,DEBUG2,DEBUG3;;log level
MACs=;;message authentication codes
PasswordAuthentication=yes,no;;password authentication
Port=;;remote port
PreferredAuthentications=;;authentication methods
ProxyCommand=;;proxy command
ProxyJump=`_choice_sftp_host`;;proxy jump hosts
PubkeyAuthentication=yes,no;;public key authentication
RequestTTY=no,yes,force,auto;;request a TTY
ServerAliveCountMax=;;server alive count
ServerAliveInterval=;;server alive interval in seconds
StrictHostKeyChecking=yes,no,ask,accept-new;;host key checking
